import csv
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

CENT = Decimal("0.01")


def parse_amount(text, line_num):
    """Parse a decimal currency amount from its CSV text form.

    Parsing goes straight from the string to Decimal; routing through float
    would bake in a binary representation error before any rounding happens.
    """
    try:
        amount = Decimal(text)
    except (InvalidOperation, TypeError, ValueError):
        raise ValueError(f"line {line_num}: invalid amount {text!r}") from None
    if not amount.is_finite():
        raise ValueError(f"line {line_num}: invalid amount {text!r}")
    return amount


def totals(path):
    """Return the exact, unrounded sum per customer as Decimal values."""
    result = {}
    with open(path, newline="") as source:
        reader = csv.DictReader(source)
        for row in reader:
            customer = row["customer"]
            amount = parse_amount(row.get("amount"), reader.line_num)
            result[customer] = result.get(customer, Decimal("0")) + amount
    return result


def rounded_totals(path):
    """Return per-customer totals rounded half up to two decimal places.

    Rounding happens once, after each customer's invoices are summed, so no
    per-invoice residue can drift into the total.
    """
    return {
        customer: total.quantize(CENT, rounding=ROUND_HALF_UP)
        for customer, total in totals(path).items()
    }


if __name__ == "__main__":
    for customer, amount in sorted(rounded_totals("invoices.csv").items()):
        print(f"{customer},{amount}")
